@using CourseCatalog.Models

<div class="card h-100 featured-course-card">
    <div class="card-body d-flex flex-column">
        <span class="badge bg-primary mb-2 align-self-start">@Course.DepartmentName</span>
        <h5 class="card-title">@Course.Id — @Course.Title</h5>
        <p class="card-text text-muted flex-grow-1">@Truncate(Course.Description, 120)</p>
        <div class="d-flex justify-content-between align-items-center mt-2">
            <small class="text-muted">@Course.Credits credits · @Course.Level</small>
            <a href="/courses/@Course.Id" class="btn btn-outline-primary btn-sm">View Details</a>
        </div>
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public Course Course { get; set; } = default!;

    private static string Truncate(string text, int maxLength) =>
        text.Length <= maxLength ? text : string.Concat(text.AsSpan(0, maxLength), "…");
}

