<h1 class="mb-4">Course Catalog</h1>

<form method="get" class="card mb-4">
    <div class="card-body">
        <div class="row g-3 align-items-end">
            <div class="col-md-4">
                <label for="search" class="form-label">Search</label>
                <input type="text" id="search" name="search" value="@Search" class="form-control" placeholder="Course name, ID, or instructor…" />
            </div>
            <div class="col-md-3">
                <label for="department" class="form-label">Department</label>
                <select id="department" name="department" class="form-select">
                    <option value="">All Departments</option>
                    @foreach (var dept in _departments)
                    {
                        <option value="@dept.Id" selected="@(dept.Id == Department)">@dept.Name</option>
                    }
                </select>
            </div>
            <div class="col-md-2">
                <label for="credits" class="form-label">Credits</label>
                <select id="credits" name="credits" class="form-select">
                    <option value="">Any</option>
                    @foreach (var c in _creditOptions)
                    {
                        <option value="@c" selected="@(c == Credits)">@c</option>
                    }
                </select>
            </div>
            <div class="col-md-2">
                <label for="level" class="form-label">Level</label>
                <select id="level" name="level" class="form-select">
                    <option value="">Any</option>
                    <option value="Undergraduate" selected="@(Level == "Undergraduate")">Undergraduate</option>
                    <option value="Graduate" selected="@(Level == "Graduate")">Graduate</option>
                </select>
            </div>
            <div class="col-md-1">
                <button type="submit" class="btn btn-primary w-100">Filter</button>
            </div>
        </div>
    </div>
</form>

<p class="text-muted mb-3">Showing @_courses.Count course(s)</p>

@if (_courses.Count == 0)
{
    <div class="alert alert-info">No courses match your filters. Try broadening your search.</div>
}
else
{
    @foreach (var course in _courses)
    {
        <CourseCard Course="course" />
    }
}

@code {
    [SupplyParameterFromQuery] public string? Search { get; set; }
    [SupplyParameterFromQuery] public string? Department { get; set; }
    [SupplyParameterFromQuery] public int? Credits { get; set; }
    [SupplyParameterFromQuery] public string? Level { get; set; }

    private IReadOnlyList<Course> _courses = [];
    private IReadOnlyList<Department> _departments = [];
    private readonly int[] _creditOptions = [3, 4];

    protected override void OnInitialized()
    {
        _departments = Catalog.GetDepartments();
        _courses = Catalog.GetCourses(Search, Department, Credits, Level);
    }
}
