                <select id="department" name="department" class="form-select">
                    <option value="">All Departments</option>
                    @foreach (var dept in _departments)
                    {
                        <option value="@dept.Id" selected="@(dept.Id == Department)">@dept.Name</option>
                    }
                </select>
            </div>
            <div class="col-md-2">
                <label for="credits" class="form-label">Credits</label>
                <select id="credits" name="credits" class="form-select">
                    <option value="">Any</option>
                    @foreach (var c in _creditOptions)
                    {
                        <option value="@c" selected="@(c == Credits)">@c</option>
                    }
                </select>
            </div>
            <div class="col-md-2">
                <label for="level" class="form-label">Level</label>
                <select id="level" name="level" class="form-select">
                    <option value="">Any</option>
                    <option value="Undergraduate" selected="@(Level == "Undergraduate")">Undergraduate</option>
                    <option value="Graduate" selected="@(Level == "Graduate")">Graduate</option>
                </select>
            </div>
            <div class="col-md-1">
                <button type="submit" class="btn btn-primary w-100">Filter</button>
            </div>
        </div>
    </div>
</form>

<p class="text-muted mb-3">Showing @_courses.Count course(s)</p>

@if (_courses.Count == 0)
{
    <div class="alert alert-info">No courses match your filters. Try broadening your search.</div>
}
else
{
    @foreach (var course in _courses)
    {
        <CourseCard Course="course" />
    }
}

@code {
    [SupplyParameterFromQuery] public string? Search { get; set; }
    [SupplyParameterFromQuery] public string? Department { get; set; }
    [SupplyParameterFromQuery] public int? Credits { get; set; }
    [SupplyParameterFromQuery] public string? Level { get; set; }

    private IReadOnlyList<Course> _courses = [];
    private IReadOnlyList<Department> _departments = [];
    private readonly int[] _creditOptions = [3, 4];

    protected override void OnInitialized()
    {
        _departments = Catalog.GetDepartments();
        _courses = Catalog.GetCourses(Search, Department, Credits, Level);
    }
}

@page "/enroll"
@using CourseCatalog.Models
@using CourseCatalog.Services
@inject ICatalogService Catalog

<PageTitle>Enroll — University Course Catalog</PageTitle>

<h1 class="mb-4">Enrollment Request</h1>

@if (_submitted)
{
    <div class="alert alert-success">
        <h4 class="alert-heading">Request Submitted!</h4>
        <p>
            Thank you, <strong>@_model.StudentName</strong>. Your enrollment request for
            <strong>@_selectedCourseTitle</strong> has been received. You will receive a
            confirmation at <strong>@_model.Email</strong>.
        </p>
        <hr />
        <a href="/courses" class="btn btn-outline-success">Browse More Courses</a>
        <a href="/enroll" class="btn btn-success ms-2">Submit Another Request</a>
    </div>
}
else
{
    <div class="row">
        <div class="col-lg-8">
            <EditForm method="post" Model="_model" OnValidSubmit="HandleSubmit" FormName="enrollment" Enhance>
                <DataAnnotationsValidator />
                <AntiforgeryToken />
                <ValidationSummary class="text-danger mb-3" />

                <div class="mb-3">
                    <label for="studentName" class="form-label">Full Name <span class="text-danger">*</span></label>
                    <InputText id="studentName" @bind-Value="_model.StudentName" class="form-control" />
                    <ValidationMessage For="() => _model.StudentName" class="text-danger" />
                </div>

                <div class="mb-3">
                    <label for="studentId" class="form-label">Student ID <span class="text-danger">*</span></label>
                    <InputText id="studentId" @bind-Value="_model.StudentId" class="form-control" placeholder="e.g. STU12345" />
                    <ValidationMessage For="() => _model.StudentId" class="text-danger" />
                </div>

                <div class="mb-3">
                    <label for="email" class="form-label">Email</label>
                    <InputText id="email" @bind-Value="_model.Email" class="form-control" placeholder="student@university.edu" />
                    <ValidationMessage For="() => _model.Email" class="text-danger" />
                </div>

                <div class="mb-3">
                    <label for="courseId" class="form-label">Course <span class="text-danger">*</span></label>
                    <InputSelect id="courseId" @bind-Value="_model.CourseId" class="form-select">
                        <option value="">— Select a course —</option>
                        @foreach (var course in _availableCourses)
                        {
                            <option value="@course.Id">@course.Id — @course.Title (@course.Credits cr)</option>
                        }
                    </InputSelect>
                    <ValidationMessage For="() => _model.CourseId" class="text-danger" />
                </div>

                <div class="mb-3">
                    <label for="comments" class="form-label">Comments (optional)</label>
                    <InputTextArea id="comments" @bind-Value="_model.Comments" class="form-control" rows="3" />
                    <ValidationMessage For="() => _model.Comments" class="text-danger" />
                </div>

                <button type="submit" class="btn btn-primary">Submit Enrollment Request</button>
                <a href="/courses" class="btn btn-link">Cancel</a>
            </EditForm>
        </div>

        <div class="col-lg-4">
            <div class="card bg-light">
                <div class="card-body">
                    <h6 class="card-title">Need Help?</h6>
                    <p class="card-text small">
                        Contact the Registrar's Office at <strong>registrar@university.edu</strong>
                        or visit Room 100 in the Administration Building during business hours.
                    </p>
                </div>
            </div>
        </div>
    </div>
}

@code {
    [SupplyParameterFromForm]
    private EnrollmentRequest _model { get; set; } = new();

    [SupplyParameterFromQuery]
    public string? CourseId { get; set; }

    private IReadOnlyList<Course> _availableCourses = [];
    private bool _submitted;
    private string _selectedCourseTitle = string.Empty;

    protected override void OnInitialized()
    {
        _availableCourses = Catalog.GetCourses()
            .Where(c => c.CurrentEnrollment < c.MaxEnrollment)
            .OrderBy(c => c.Id)
            .ToList();

        if (!string.IsNullOrEmpty(CourseId) && string.IsNullOrEmpty(_model.CourseId))
            _model.CourseId = CourseId;
    }

    private void HandleSubmit()
    {
        var course = Catalog.GetCourse(_model.CourseId);
        _selectedCourseTitle = course is not null ? $"{course.Id} — {course.Title}" : _model.CourseId;
        _submitted = Catalog.SubmitEnrollment(_model);
    }
}

